<script setup>
import { computed, inject,ref,watch } from 'vue'
import { objectWrite } from '../../data-object-api.js'
import { ElMessage } from 'element-plus'
import DictionaryPicker from './DictionaryPicker.vue'
const can=inject('canPermission',()=>false),dictionaryOpen=ref(false)
function addDictionary({fields:chosen,missingLength}){if(fields.value.length===1&&!fields.value[0].name.trim())fields.value=[];fields.value.push(...chosen);if(missingLength.length)ElMessage.warning(`请补填字段长度：${missingLength.join('、')}`)}
const props=defineProps({modelValue:Boolean,object:Object,source:Object})
const emit=defineEmits(['update:modelValue','published'])
const fields=ref([]),plan=ref(null),busy=ref(false),error=ref('')
const types=computed(()=>props.source?.type==='MYSQL'?['VARCHAR','CHAR','INT','BIGINT','DECIMAL','DATE','DATETIME']:props.source?.type==='POSTGRESQL'?['VARCHAR','CHAR','INTEGER','BIGINT','NUMERIC','DATE','TIMESTAMP']:['VARCHAR2','CHAR','NUMBER','DATE','TIMESTAMP'])
watch(()=>props.modelValue,open=>{if(open){plan.value=null;error.value='';fields.value=(props.object?.fields||[]).map(f=>{let t=f.type.toUpperCase();return {name:f.name,type:t,length:['VARCHAR','VARCHAR2','CHAR','DECIMAL','NUMERIC','NUMBER'].includes(t)?f.length:null,scale:['DECIMAL','NUMERIC','NUMBER'].includes(t)?f.scale:null,nullable:f.nullable==='YES',primaryKey:f.primaryKey==='YES'}})}})
async function preview(){try{busy.value=true;error.value='';plan.value=await objectWrite(`/api/data-objects/${props.object.object.id}/schema-preview`,'POST',{fields:fields.value})}catch(e){error.value=e.message}finally{busy.value=false}}
async function execute(){try{busy.value=true;error.value='';plan.value=await objectWrite(`/api/data-object-schema-operations/${plan.value.operationId}/execute`,'POST',{});if(plan.value.status==='SUCCEEDED')emit('published')}catch(e){error.value=e.message}finally{busy.value=false}}
async function cancel(){try{await objectWrite(`/api/data-object-schema-operations/${plan.value.operationId}`,'DELETE');plan.value=null}catch(e){error.value=e.message}}
</script>
<template><el-dialog :model-value="modelValue" title="编辑字段结构" width="min(1050px,96vw)" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="plan?.status!=='PREPARED'" @update:model-value="emit('update:modelValue',$event)"><el-alert v-if="error" :title="error" type="error" show-icon/><template v-if="!plan"><el-alert title="不支持修改主键、重命名字段或修改视图。删除字段、缩短长度和改变类型可能造成数据丢失。" type="warning" :closable="false"/><div class="heading"><b>字段定义</b><div><el-button v-if="can('datasource.dictionary.read')" :disabled="!source" @click="dictionaryOpen=true">从字典选择</el-button><el-button @click="fields.push({name:'',type:types[0],length:null,scale:null,nullable:true,primaryKey:false})">添加字段</el-button></div></div><el-table :data="fields" max-height="400"><el-table-column label="字段名" min-width="130"><template #default="s"><el-input v-model="s.row.name" :disabled="s.row.primaryKey"/></template></el-table-column><el-table-column label="类型" min-width="120"><template #default="s"><el-select v-model="s.row.type"><el-option v-if="!types.includes(s.row.type)" :label="s.row.type+'（原生类型）'" :value="s.row.type"/><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select></template></el-table-column><el-table-column label="长度" width="110"><template #default="s"><el-input-number v-model="s.row.length" :min="1" :controls="false"/></template></el-table-column><el-table-column label="小数位" width="100"><template #default="s"><el-input-number v-model="s.row.scale" :min="0" :controls="false"/></template></el-table-column><el-table-column label="可空" width="70"><template #default="s"><el-checkbox v-model="s.row.nullable" :disabled="s.row.primaryKey"/></template></el-table-column><el-table-column label="主键" width="70"><template #default="s">{{s.row.primaryKey?'是':'否'}}</template></el-table-column><el-table-column label="注释" min-width="150"><template #default="s"><el-input v-model="s.row.remarks" :disabled="object?.fields?.some(f=>f.name===s.row.name)" maxlength="1000"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="s"><el-button link type="danger" :disabled="s.row.primaryKey" @click="fields.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></template><template v-else><el-alert :title="plan.status==='PREPARED'?'请仔细核对目标数据库、变更语句和风险，确认后将直接修改物理表。':`执行状态：${plan.status}`" :type="plan.status==='SUCCEEDED'?'success':'warning'" :closable="false"/><p>目标：{{plan.identity.catalog||'—'}} / {{plan.identity.schema||'—'}} / {{plan.identity.table}}</p><div v-for="(change,index) in plan.changes" :key="index"><pre>{{change.sql}}</pre><p v-if="change.risk" class="risk">{{change.risk}}</p></div><p v-if="['UNKNOWN','PARTIAL'].includes(plan.status)">数据库操作可能部分完成，请检查实际表结构。系统不会自动重试。</p></template><template #footer><el-button v-if="!plan||plan.status!=='PREPARED'" @click="emit('update:modelValue',false)">关闭</el-button><el-button v-if="plan?.status==='PREPARED'" :disabled="busy" @click="cancel">返回编辑</el-button><el-button v-if="!plan" type="primary" :loading="busy" @click="preview">预览变更</el-button><el-button v-else-if="plan.status==='PREPARED'" type="danger" :loading="busy" @click="execute">确认发布</el-button></template></el-dialog><DictionaryPicker v-model="dictionaryOpen" :source-type="source?.type" :existing="fields" @select="addDictionary"/></template>
<style scoped>.heading{display:flex;justify-content:space-between;margin:14px 0}.el-input-number{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fa;padding:12px}.risk{color:#c45600}</style>
